import { exec } from 'child_process';
import { promisify } from 'util';
import type { Channel, ConsumeMessage } from 'amqplib';

const execAsync = promisify(exec);

// POSIX sh 单引号上下文编码器：单引号内部除单引号字符外，任何字符均无特殊含义，
// 故将输入中每个单引号重编码为 '\''（先闭引号、再转义引号、后重开引号），
// 编码结果只能被 /bin/sh 解析为单个字面量参数，无法改变命令结构。
function shEncode(value: string): string {
  let encoded = "'";
  for (const ch of value) {
    encoded += ch === "'" ? "'\\''" : ch;
  }
  return encoded + "'";
}

interface CompressJob {
  filePath: string;
}

export async function onCompressTask(msg: ConsumeMessage, channel: Channel): Promise<void> {
  const job = JSON.parse(msg.content.toString('utf8')) as CompressJob;
  if (typeof job.filePath !== 'string') throw new Error('invalid job');

  // 表面危险：exec 以字符串拼接方式启动 shell，呈现 CWE-78 命令注入形态
  const cmd = `gzip -c ${shEncode(job.filePath)} >> /var/archive/upload.log.gz`;
  const { stdout } = await execAsync(cmd, { shell: '/bin/sh', timeout: 30_000 });

  console.log(`compressed, stdout ${stdout.length} bytes`);
  channel.ack(msg);
}
```
1. 来源识别：第 23 行 JSON.parse(msg.content.toString('utf8')) 把消息队列消息体解析为 job，其 filePath 字段完全由消息生产者控制，是本数据流唯一的不可信来源；第 24 行类型守卫在非字符串时直接抛错，保证后续处理 fail-closed。
2. 危险汇聚点：第 27 行把 job.filePath 经模板字符串拼入 cmd，第 28 行传入 execAsync（第 5 行由 child_process.exec 包装而来）且 shell 选项显式为 /bin/sh，表面构成 CWE-78 命令注入的典型拼接执行形态。
3. 防御机制与位置：第 10 至 16 行的 shEncode 是 POSIX sh 单引号上下文的正向完整编码器，在数据写入命令字符串的输出点（第 27 行）生效——输出整体以单引号包裹，第 13 行把输入中每个单引号字符重编码为 '\'' 三段序列（闭合引号、转义引号、重新开引号），其余字符逐字保留；由于单引号内部除单引号外的一切字符（分号、竖线、美元符、反引号、反斜杠、换行、空格）均失去元字符语义，攻击载荷无法提前终止引号或改变命令结构，该防御不依赖黑名单、不依赖正则匹配、不做危险子串删除，属于与 HTML 实体编码同级的上下文编码，且第 28 行将解释器固定为 /bin/sh，使编码假设与真实执行上下文严格一致。
4. 覆盖面核验：第 27 行命令模板中唯一可变片段就是 shEncode(job.filePath) 的返回值，重定向目标 /var/archive/upload.log.gz 为字面常量，不存在任何未编码的插值点，编码覆盖完整无遗漏。
5. 替代通道检查：消息对象除 filePath 外的字段未被读取，msg.fields 等路由元数据未参与命令构造，第 30 行仅取 stdout.length 写日志、未进入任何二次执行或存储后回显点，全文件不存在第二个 exec 或 spawn 调用，因此不存在绕过编码防御的替代数据流，综合判定该数据流安全。
