using System;
using System.Data;
using System.Data.SqlClient;
using System.IO;

public class UploadMetadataService
{
    // 连接串走 Windows 集成认证，不含任何口令或密钥
    private const string ConnectionString = "Server=localhost;Database=FileVault;Integrated Security=SSPI;";

    // rawFileName 与 ownerName 直接来自 HTTP 上传表单，均为外部输入
    public void SaveMetadata(string rawFileName, string ownerName, long sizeBytes)
    {
        string safeName = Path.GetFileName(rawFileName ?? string.Empty);

        // 注意：此处以 + 号拼接构造 SQL 文本，形态上是典型的拼接查询高危写法，
        // 但所有拼接段均为编译期常量，外部输入一律只允许经参数绑定进入执行层
        string sql = "INSERT INTO dbo.UploadMetadata"
                   + " (FileName, Owner, SizeBytes, UploadedAt)"
                   + " VALUES (@fileName, @owner, @size, SYSUTCDATETIME())";

        using (var conn = new SqlConnection(ConnectionString))
        using (var cmd = new SqlCommand(sql, conn))
        {
            cmd.CommandType = CommandType.Text;
            // 防御点：汇点处的上下文编码——SqlParameter 使驱动按声明类型
            // 将值与 SQL 文本分通道传输，值永不参与语句解析，无法闭合引号
            cmd.Parameters.Add("@fileName", SqlDbType.NVarChar, 260).Value = safeName;
            cmd.Parameters.Add("@owner", SqlDbType.NVarChar, 64).Value = ownerName ?? "anonymous";
            cmd.Parameters.Add("@size", SqlDbType.BigInt).Value = sizeBytes;

            conn.Open();
            cmd.ExecuteNonQuery();
        }
    }
}
```
1. 数据流起点：第12行 SaveMetadata 的形参 rawFileName 与 ownerName 直接来自上传表单，属外部输入；第14行经 Path.GetFileName 归一化得到 safeName，该步骤仅剥离路径部分，不构成 SQL 注入防御本体。
2. 表面危险模式：第18至20行用 + 号拼接构造 SQL 文本赋给 sql，第23行传入 new SqlCommand，第25行设 CommandType.Text，第33行 cmd.ExecuteNonQuery 执行，整体呈现 CWE-89 拼接查询的高危形态。
3. 真实防御与位置：第28至30行通过 cmd.Parameters.Add 将 safeName、ownerName、sizeBytes 全部绑定为 SqlParameter，由 ADO.NET 驱动在执行期按 NVarChar 与 BigInt 声明类型将值与 SQL 文本分通道编码传输，值永不进入语句文本，无法闭合引号或改写结构，属于汇点处的上下文编码防御，且非黑名单、非正则、非字符串替换。
4. 覆盖面核查：第18至20行所有拼接段均为编译期字符串字面量，不含任何变量插值，外部输入没有第二条路径进入 sql 文本；第23行 CommandText 仅赋值一次，此后无任何二次改写，防御覆盖方法内全部三个外部输入。
