using System;
using System.Security.Cryptography;
using System.Text;

public enum UpstreamSignAlg { HmacSha256 = 1, HmacSha384 = 2, HmacSha512 = 3, Md5 = 90, Sha1 = 91 }

public static class ForwardSigner
{
    // 白名单精确映射：仅三个强 HMAC 实现可被构造，Md5/Sha1 落入 default 分支被拒绝
    private static HMAC Resolve(UpstreamSignAlg alg)
    {
        switch (alg)
        {
            case UpstreamSignAlg.HmacSha256: return new HMACSHA256();
            case UpstreamSignAlg.HmacSha384: return new HMACSHA384();
            case UpstreamSignAlg.HmacSha512: return new HMACSHA512();
            default: throw new InvalidOperationException("algorithm rejected by whitelist");
        }
    }

    // 网关转发前对上游请求计算签名；algHeader 来自入站请求头，属攻击者可控输入
    public static byte[] Sign(string upstreamPath, byte[] body, string algHeader)
    {
        if (!Enum.TryParse(algHeader, false, out UpstreamSignAlg alg) ||
            !Enum.IsDefined(typeof(UpstreamSignAlg), alg))
            throw new ArgumentException("unsupported signature algorithm");
        using (HMAC h = Resolve(alg))
        {
            byte[] key = Convert.FromBase64String(Environment.GetEnvironmentVariable("GW_FWD_HMAC_KEY"));
            if (key.Length < 32) throw new InvalidOperationException("key material too short");
            h.Key = key;
            byte[] p = Encoding.UTF8.GetBytes(upstreamPath ?? "/");
            h.TransformBlock(p, 0, p.Length, null, 0);
            byte[] b = body ?? new byte[0];
            h.TransformFinalBlock(b, 0, b.Length);
            return h.Hash;
        }
    }
}
```

1. 数据流起点：第 22 行 Sign 方法的第 3 参 algHeader 来自入站请求头，属攻击者可控输入，且第 5 行枚举 UpstreamSignAlg 中保留了 Md5 与 Sha1 成员，表面构成 CWE-327 算法协商降级的危险模式。
2. 第一道防御（入口严格解析）：第 24 行 Enum.TryParse 以区分大小写模式解析 algHeader，第 25 行 Enum.IsDefined 再次校验枚举成员真实存在，未定义名称、大小写变体或越界数值（如 7）均在第 26 行抛出 ArgumentException，非法输入无法进入算法构造阶段。
3. 第二道防御（白名单精确映射）：第 10 行 Resolve 仅在第 14 至 16 行把 HmacSha256、HmacSha384、HmacSha512 精确映射到 HMACSHA256、HMACSHA384、HMACSHA512 三个强实现；M

