```kotlin
import java.io.File

const val WEB_ROOT = "/var/www/static"

// 静态资源服务：根据用户请求的相对路径返回本地文件内容
fun serveStaticResource(requestPath: String): ByteArray? {
    // 入口预检：拒绝空路径、绝对路径与反斜杠，封堵分隔符变体通道
    if (requestPath.isEmpty() || requestPath.startsWith("/") || requestPath.contains("\\")) return null
    val requested = File(WEB_ROOT, requestPath)
    // 规范化：解析全部 ../ 与 ./ 及符号链接，任何异常一律拒绝
    val canonical = try { requested.canonicalFile } catch (e: Exception) { return null }
    val root = File(WEB_ROOT).canonicalFile
    // 双重校验之一：规范化字符串前缀比对，必须落在根目录分隔符之后
    val prefixOk = canonical.path == root.path ||
            canonical.path.startsWith(root.path + File.separator)
    // 双重校验之二：Path 组件级 startsWith，排除兄弟目录前缀误判
    val componentOk = canonical.toPath().startsWith(root.toPath())
    if (!prefixOk || !componentOk) return null
    // 仅允许常规文件，拒绝目录与特殊文件
    if (!canonical.isFile) return null
    return canonical.readBytes()
}
```
1. 数据流起点：第6行 serveStaticResource 的参数 requestPath 来自外部请求，第9行 File(WEB_ROOT, requestPath) 将其拼入根目录，表面形成可被 ../ 穿越的 CWE-22 源到汇链，终点看似为第21行 readBytes。
2. 防御位置一：第11行 requested.canonicalFile 在任何比较之前对路径做完整规范化，还原全部 ../ 与 ./ 并把符号链接解析为真实目标，规范化抛出异常时同一行直接返回 null 拒绝请求。
3. 防御位置二：第14至15行 prefixOk 用规范化后的字符串要求结果等于根或位于 root.path 加分隔符之后，第17行 componentOk 再用 Path.startsWith 做组件级二次校验，两道校验任一失败即在第18行返回 null，构成 canonical path 双重校验，且 /var/www/static 等兄弟目录前缀不会被误放行。
4. 覆盖面：由于规范化先于校验执行，编码残留、多点穿越、符号链接指向根外等变形在第11行已被还原为真实路径并由第18行统一拦截，第20行 isFile 进一步把可读对象限制为根内常规文件，防御覆盖全部到达 readBytes 的路径。
5. 替代通道检查：反斜杠与绝对路径在第8行被拒；上游完成 URL 解码后残留的编码字面量只会成为根内普通文件名；函数内不存在第二条绕过校验的文件读取通道，readBytes 仅作用于通过双重校验的 canonical，故该数据流安全。

