```kotlin
package com.example.richtext

import java.io.ByteArrayInputStream
import java.io.ObjectInputFilter
import java.io.ObjectInputStream
import java.io.ObjectStreamClass

// 富文本处理模块：从同步通道恢复序列化的富文本文档（表面为 CWE-502 原生反序列化）
data class RichTextSpan(val start: Int, val end: Int, val style: String)
data class RichTextDocument(val title: String, val body: String, val spans: ArrayList<RichTextSpan>)

object RichTextRestorer {

    // 防御一：JVM 级反序列化白名单过滤器，未列出的类一律拒绝
    private val SAFE_FILTER = ObjectInputFilter { info ->
        val tooDeep = info.depth() > 8 || info.references() > 200
        val c = info.serialClass()
        when {
            tooDeep -> ObjectInputFilter.Status.REJECTED
            c == null -> ObjectInputFilter.Status.ALLOWED
            c == RichTextDocument::class.java || c == RichTextSpan::class.java ||
                c == String::class.java || c == java.lang.Integer::class.java ||
                c == java.util.ArrayList::class.java -> ObjectInputFilter.Status.ALLOWED
            else -> ObjectInputFilter.Status.REJECTED
        }
    }

    fun restore(payload: ByteArray): RichTextDocument {
        val ois = object : ObjectInputStream(ByteArrayInputStream(payload)) {
            // 防御二：resolveClass 精确等值校验，流中出现任何其他类名立即终止
            override fun resolveClass(desc: ObjectStreamClass): Class<*> {
                require(desc.name in setOf(
                    RichTextDocument::class.java.name, RichTextSpan::class.java.name,
                    "java.lang.String", "java.lang.Integer", "java.util.ArrayList"
                )) { "illegal class in stream: " + desc.name }
                return super.resolveClass(desc)
            }
        }
        ois.setObjectInputFilter(SAFE_FILTER)
        try {
            return ois.readObject() as RichTextDocument
        } finally {
            ois.close()
        }
    }
}
```
1. 数据流起点与表面风险：restore 函数（第 27 行）接收外部传入的序列化字节 payload，经 ByteArrayInputStream 进入第 28 行的 ObjectInputStream，最终抵达第 40 行 ois.
